importScripts('ambient-core.js','heartbeat-core.js','scene-batch-core.js','loop-core.js');
self.onmessage=e=>{try{const {channels,sampleRate,ids,options,name,folder}=e.data,files=[],manifest={source:name,created:new Date().toISOString(),folder,options,scenes:[],note:'Scene bakes are heuristic variations. Audition phrase boundaries and tails. These files fade at their edges and are not certified seamless loops. Downed changes pitch with speed. Ambient full-track mode is capped at 60 seconds.'};
 for(let i=0;i<ids.length;i++){self.postMessage({progress:i/ids.length*100,status:`Rendering ${i+1} of ${ids.length}: ${ids[i]}…`});const r=PulseSceneBatch.render(channels,sampleRate,ids[i],options),file=PulseSceneBatch.safeName(name)+'_'+ids[i]+'.wav';files.push({name:folder+'/'+file,data:PulseAssets.wav(r.channels,sampleRate)});manifest.scenes.push({scene:ids[i],file,startSeconds:r.start,durationSeconds:r.seconds,processing:r.rate})}
 files.push({name:folder+'/manifest.json',data:JSON.stringify(manifest,null,2)},{name:folder+'/READ-ME.txt',data:manifest.note+'\n\nFiles were processed locally. No game engine is required.\n'});self.postMessage({status:'Packing scene files…',progress:95});self.postMessage({done:true,blob:PulseAssets.zip(files),manifest});
}catch(e){self.postMessage({error:e.message})}};
